    payload = {
        "sheetName": "Data Ads",
        "sheetType": "ads",
        "data": [ { "Tanggal": "01/05/2026", "Lead": "50" } ]
    }
    headers = {
        "Content-Type": "application/json"
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
